import React, { useState, useMemo, useEffect } from 'react';
import './Board.css';
import { getValueFromCoordinates, getCoordinatesFromValue } from './coordinates.js';

const Board = ({ gameData, socket }) => {
  const gridSize = 11;
  const centerIndex = Math.floor(gridSize / 2);

  const { pieces: initialPieces } = gameData.board;
  const { players } = gameData;

  const [pieces, setPieces] = useState(initialPieces);
  const [error, setError] = useState(null);
  const [statusMessage, setStatusMessage] = useState("");

  useEffect(() => {
    if (!socket) return;

    // Event listeners for socket connection and disconnection
    socket.on('connect', () => {
      console.log('Socket connected: ', socket.id);
    });

    socket.on('disconnect', () => {
      console.log('Disconnected from server.');
    });

    // Handle game updates
    socket.on('game:updated', (data) => {
      const { updatedPiece, nextPlayerId } = data;
      console.log('Received response from server:', data);
      if (updatedPiece) {
        const { ownerId, color, commonPosition } = updatedPiece;
        console.log(`Player ${ownerId} moved ${color} piece to position ${commonPosition}`);

        // Update the piece position in the state
        setPieces(prevPieces =>
          prevPieces.map(piece =>
            piece.ownerId === ownerId && piece.color === color
              ? { ...piece, position: commonPosition }
              : piece
          )
        );

        if (nextPlayerId) {
          setStatusMessage(`It's player ${nextPlayerId}'s turn.`);
        }
      }
    });

    // Handle dice rolls
    socket.on('game:diceRolled', (data) => {
      const { playerId, dice, canDeploy } = data;
      setDiceRoll(dice);
      setStatusMessage(`Player ${playerId} rolled a ${dice}.`);

      if (canDeploy) {
        setStatusMessage(`Player ${playerId} can deploy a new piece!`);
      }
    });

    // Cleanup event listeners when the component is unmounted
    return () => {
      socket.off('game:updated');
      socket.off('game:diceRolled');
    };
  }, [socket]);

  // Precompute tile colorsz
  const tileColorMap = useMemo(() => {
    const colorMap = new Map();
    players.forEach((player, index) => {
      let tiles = [];
      if (index === 0) {
        tiles = [
          [4, 0], [5, 1], [5, 2], [5, 3], [5, 4], [0, 0], [0, 1], [1, 0], [1, 1]
        ];
      } else if (index === 1) {
        tiles = [
          [0, 6], [1, 5], [2, 5], [3, 5], [4, 5], [0, 9], [0, 10], [1, 9], [1, 10]
        ];
      } else if (index === 2) {
        tiles = [
          [6, 10], [5, 6], [5, 7], [5, 8], [5, 9], [9, 9], [10, 9], [9, 10], [10, 10]
        ];
      } else if (index === 3) {
        tiles = [
          [10, 4], [6, 5], [7, 5], [8, 5], [9, 5], [9, 0], [9, 1], [10, 0], [10, 1]
        ];
      }

      tiles.forEach(([row, col]) => {
        colorMap.set(`${row}-${col}`, player.color);
      });
    });
    return colorMap;
  }, [players]);

  // Precompute piece positions
  const pieceMap = useMemo(() => {
    const map = new Map();
    pieces.forEach(piece => {
      const { row, col } = getCoordinatesFromValue(piece.commonPosition, piece.color);
      map.set(`${row}-${col}`, piece);
    });
    return map;
  }, [pieces]);

  const isCrossTile = (row, col) => {
    if (row === centerIndex && col === centerIndex) return false;
    return (
      (col >= centerIndex - 1 && col <= centerIndex + 1) ||
      (row >= centerIndex - 1 && row <= centerIndex + 1) ||
      (row <= 1 && col <= 1) ||
      (row >= 9 && col >= 9) ||
      (row <= 1 && col >= 9) ||
      (row >= 9 && col <= 1)
    );
  };

  const getTileColor = (row, col) => {
    if (!isCrossTile(row, col)) return 'white';
    return tileColorMap.get(`${row}-${col}`) || 'white';
  };

  const renderPiece = (row, col) => {
    const piece = pieceMap.get(`${row}-${col}`);
    return piece ? (
      <div
        className="piece"
        style={{ backgroundColor: piece.color, width: '70%', height: '70%' }}
      ></div>
    ) : null;
  };

  return (
    <div className="board">
      {Array.from({ length: gridSize }).map((_, row) => (
        <div key={row} className="board-row">
          {Array.from({ length: gridSize }).map((_, col) => (
            <div
              key={`${row}-${col}`}
              className={`tile ${isCrossTile(row, col) ? '' : 'empty-tile'}`}
              style={{
                backgroundColor: getTileColor(row, col),
              }}
            >
              {renderPiece(row, col)}
            </div>
          ))}
        </div>
      ))}
      {statusMessage && <div className="status-message">{statusMessage}</div>}
      {error && <div className="error">{error}</div>}
    </div>
  );
};

export default Board;
